-- Electrodomesticos - seed Neon (categories + produits)
CREATE TABLE IF NOT EXISTS categories (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, type TEXT NOT NULL,
  iconKey TEXT NOT NULL, description TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS products (
  id INTEGER PRIMARY KEY, name TEXT NOT NULL, slug TEXT UNIQUE NOT NULL,
  category TEXT NOT NULL REFERENCES categories(id),
  price DOUBLE PRECISION NOT NULL, oldPrice DOUBLE PRECISION, badge TEXT,
  rating DOUBLE PRECISION NOT NULL, reviews INTEGER NOT NULL,
  features JSONB NOT NULL, description TEXT NOT NULL, specs JSONB NOT NULL,
  image TEXT, images JSONB DEFAULT '[]'::jsonb, stock INTEGER NOT NULL DEFAULT 10,
  brand TEXT, gtin TEXT, mpn TEXT
);

